use serde::{Deserialize, Serialize};

/// Final outcome of a run — persisted to `result.json`.
///
/// v0.6 non-compatible redesign: new status variants, typed step status, per-step usage.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RunResult {
    pub run_id: String,
    pub task_id: String,
    pub status: RunStatus,
    pub started_at: i64,
    pub finished_at: Option<i64>,
    pub steps: Vec<StepOutcome>,
    pub usage: UsageSummary,
    pub error: Option<String>,
    pub cost_usd: Option<f64>,
    /// Human-readable summary generated by the LLM after run completion.
    /// Written in the user's language (zh/en) based on locale.
    #[serde(default)]
    pub summary: Option<String>,
}

/// Run-level status machine — 7 states, 9 transitions.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum RunStatus {
    /// Submitted, waiting for a worker to pick up.
    Queued,
    /// Worker is executing steps.
    Running,
    /// A step produced rework items; waiting for child runs to complete.
    AwaitingRework,
    /// A Write step with `requires_approval=true` is paused for user review.
    AwaitingApproval,
    /// All steps finished successfully.
    Complete,
    /// Cancelled by user or supervisor.
    Aborted,
    /// A step or the run itself failed.
    Error,
}

impl RunStatus {
    /// Terminal states — no further transitions expected.
    pub fn is_terminal(&self) -> bool {
        matches!(
            self,
            RunStatus::Complete | RunStatus::Aborted | RunStatus::Error
        )
    }

    /// Active states — daemon should track these for recovery.
    pub fn is_active(&self) -> bool {
        matches!(
            self,
            RunStatus::Queued
                | RunStatus::Running
                | RunStatus::AwaitingRework
                | RunStatus::AwaitingApproval
        )
    }
}

/// Per-step execution outcome — worker writes this, not the agent.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct StepOutcome {
    pub step_id: String,
    pub role_id: String,
    pub agent_id: String,
    /// Display name of the agent (e.g., "Claude Code" not "claude-code") — for UI
    #[serde(default)]
    pub agent_display_name: Option<String>,
    pub status: StepStatus,
    /// Worker-populated from agent output / trace.
    pub output: Option<serde_json::Value>,
    /// Session ID returned by the agent subprocess (if any) — clickable link
    #[serde(default)]
    pub session_id: Option<String>,
    pub started_at: i64,
    pub finished_at: i64,
    pub usage: UsageSummary,
}

impl StepOutcome {
    /// Minimal constructor for tests / placeholders.
    pub fn minimal(step_id: impl Into<String>, agent_id: impl Into<String>) -> Self {
        Self {
            step_id: step_id.into(),
            role_id: String::new(),
            agent_id: agent_id.into(),
            agent_display_name: None,
            status: StepStatus::Complete,
            output: None,
            session_id: None,
            started_at: 0,
            finished_at: 0,
            usage: UsageSummary::zero(),
        }
    }
}

impl Default for StepStatus {
    fn default() -> Self {
        StepStatus::Complete
    }
}

/// Strongly typed step status — replaces stringly-typed status.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum StepStatus {
    /// Step is currently running (interim state written incrementally).
    Running,
    /// Step completed successfully.
    Complete,
    /// Step failed (agent error, non-zero exit, verification failed).
    Failed,
    /// Step skipped (dependency failed, or cancelled before execution).
    Skipped,
    /// Step is paused waiting for user approval / clarification.
    AwaitingApproval,
}

/// Token usage and cost summary.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct UsageSummary {
    pub input_tokens: u64,
    pub output_tokens: u64,
    pub cost_usd: f64,
}

impl UsageSummary {
    pub fn zero() -> Self {
        Self::default()
    }

    pub fn add(&mut self, other: &UsageSummary) {
        self.input_tokens += other.input_tokens;
        self.output_tokens += other.output_tokens;
        self.cost_usd += other.cost_usd;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn run_status_roundtrip() {
        let statuses = vec![
            RunStatus::Queued,
            RunStatus::Running,
            RunStatus::AwaitingRework,
            RunStatus::AwaitingApproval,
            RunStatus::Complete,
            RunStatus::Aborted,
            RunStatus::Error,
        ];
        for status in &statuses {
            let json = serde_json::to_string(status).unwrap();
            let de: RunStatus = serde_json::from_str(&json).unwrap();
            assert_eq!(status, &de);
        }
    }

    #[test]
    fn run_status_terminal_and_active() {
        assert!(RunStatus::Complete.is_terminal());
        assert!(RunStatus::Aborted.is_terminal());
        assert!(RunStatus::Error.is_terminal());
        assert!(!RunStatus::Running.is_terminal());

        assert!(RunStatus::Queued.is_active());
        assert!(RunStatus::Running.is_active());
        assert!(RunStatus::AwaitingRework.is_active());
        assert!(RunStatus::AwaitingApproval.is_active());
        assert!(!RunStatus::Complete.is_active());
    }

    #[test]
    fn step_outcome_roundtrip() {
        let outcome = StepOutcome {
            step_id: "sp_0".into(),
            role_id: "developer".into(),
            agent_id: "claude-code".into(),
            status: StepStatus::Complete,
            output: Some(serde_json::json!({ "files_changed": 3 })),
            started_at: 1700000000,
            finished_at: 1700000060,
            usage: UsageSummary {
                input_tokens: 1000,
                output_tokens: 500,
                cost_usd: 0.05,
            },
        ..Default::default()};
        let json = serde_json::to_string(&outcome).unwrap();
        let de: StepOutcome = serde_json::from_str(&json).unwrap();
        assert_eq!(outcome.step_id, de.step_id);
        assert_eq!(outcome.role_id, de.role_id);
        assert_eq!(outcome.status, StepStatus::Complete);
        assert_eq!(de.usage.input_tokens, 1000);
    }

    #[test]
    fn usage_summary_add() {
        let mut a = UsageSummary {
            input_tokens: 100,
            output_tokens: 50,
            cost_usd: 0.01,
        };
        let b = UsageSummary {
            input_tokens: 200,
            output_tokens: 100,
            cost_usd: 0.02,
        };
        a.add(&b);
        assert_eq!(a.input_tokens, 300);
        assert_eq!(a.output_tokens, 150);
        assert!((a.cost_usd - 0.03).abs() < f64::EPSILON);
    }

    #[test]
    fn run_result_full_roundtrip() {
        let result = RunResult {
            run_id: "r_123".into(),
            task_id: "ts_456".into(),
            status: RunStatus::Complete,
            started_at: 1700000000,
            finished_at: Some(1700000060),
            steps: vec![StepOutcome {
                step_id: "sp_0".into(),
                role_id: "developer".into(),
                agent_id: "claude-code".into(),
                status: StepStatus::Complete,
                output: None,
                started_at: 1700000000,
                finished_at: 1700000060,
                usage: UsageSummary::zero(),
                ..Default::default()
            }],
            usage: UsageSummary::zero(),
            error: None,
            cost_usd: Some(0.05),
            summary: None,
        };
        let json = serde_json::to_string(&result).unwrap();
        let de: RunResult = serde_json::from_str(&json).unwrap();
        assert_eq!(result.run_id, de.run_id);
        assert_eq!(de.status, RunStatus::Complete);
        assert_eq!(de.cost_usd, Some(0.05));
    }
}
